window.LISTENING_SECTIONS = [
  {"id":"ls-001","section":1,"title":"Booking an evening Italian course","context_ar":"محادثة هاتفية بين موظفة استقبال في مركز لغات ومتصلة تريد التسجيل في دورة إيطالية مسائية للمبتدئين","turns":[{"s":"A","text":"Good morning, Larkfield Language Centre, Denise speaking. How can I help?"},{"s":"B","text":"Oh, hello. I'm calling about your evening classes. I saw a poster in the library for a beginners' Italian course, and I wondered whether there were any places left."},{"s":"A","text":"Yes, we've got a few. I can take your details now, if you like. Could I have your surname, please?"},{"s":"B","text":"It's Pardoe."},{"s":"A","text":"Sorry, could you spell that for me?"},{"s":"B","text":"Of course. P, A, R, D, O, E."},{"s":"A","text":"P, A, R, D, O, E. Pardoe. Thank you. And may I ask why you've decided to learn Italian? It helps the teachers to plan their lessons."},{"s":"B","text":"Well, my sister and I are travelling to Sicily next June, and I'd like to manage something more than ordering a coffee."},{"s":"A","text":"That sounds like a wonderful trip. Have you studied any Italian before?"},{"s":"B","text":"Only a few phrases from a holiday years ago, so I'm certainly a beginner."},{"s":"A","text":"Then you'll be fine. The course assumes no previous knowledge."},{"s":"B","text":"Good. The poster said it begins on 7th October. Is that right?"},{"s":"A","text":"Ah, I'm afraid that's on the old leaflet. We had to move everything back a week, so it now starts on 14th October."},{"s":"B","text":"That's fine. And it's on Tuesday evenings, isn't it?"},{"s":"A","text":"It was, but the Tuesday group filled up very quickly, so we've opened a second group on Thursdays, with the same teacher."},{"s":"B","text":"Thursday would actually suit me better, because I play badminton on Tuesdays."},{"s":"A","text":"Then I'll put you down for Thursday."},{"s":"B","text":"What time does it start? Is it seven o'clock?"},{"s":"A","text":"Not quite. It starts at 7.15 and finishes at 9.15, with a short break in the middle for coffee."},{"s":"B","text":"Perfect. And where will the class be held?"},{"s":"A","text":"Let me check the timetable. It's in Room 14. No, sorry, I was looking at the wrong column. It's Room 41, on the fourth floor. There's a lift if you'd rather not take the stairs."},{"s":"B","text":"Good to know. How much is the course?"},{"s":"A","text":"It's ten weeks in total, and the normal fee is £180. But there's an early booking price of £160 if you pay before the end of this month."},{"s":"B","text":"That's good. Do I need to buy a book as well?"},{"s":"A","text":"Yes, you'll need the course book. It costs £28, and you can collect it from reception on the first evening."},{"s":"B","text":"OK. Could I pay for the course by card now, over the phone?"},{"s":"A","text":"Normally yes, but our card machine is being repaired this week, and the online payment page isn't working either. So you'd have to pay in person at reception. We're open until eight o'clock on weekdays."},{"s":"B","text":"Then I'll call in on Friday after work and pay at reception."},{"s":"A","text":"Lovely. We'll hold your place until then."},{"s":"B","text":"One last thing. Is there anywhere to park?"},{"s":"A","text":"Don't use the road at the front, because it's permit parking only. There's a small car park behind the building, and you reach it from Mill Lane."},{"s":"B","text":"Thank you very much. See you on Friday."},{"s":"A","text":"Goodbye, Miss Pardoe. Thanks for calling."}],"questions":[{"id":"q1","type":"gap","prompt":"Surname: ___","answer":"Pardoe","max_words":1,"evidence":"P, A, R, D, O, E. Pardoe","why_ar":"يُهجّى اللقب حرفًا حرفًا ثم تكرّره الموظفة: «P, A, R, D, O, E. Pardoe»، فالجواب Pardoe."},{"id":"q2","type":"mcq","prompt":"Why does the caller want to learn Italian?","options":["She wants to help a relative","She plans to study in Italy","She is preparing for a holiday","She needs it for her job"],"answer":"C","evidence":"my sister and I are travelling to Sicily next June","why_ar":"تقول المتصلة: «my sister and I are travelling to Sicily next June»، أي أنها تستعد لرحلة سفر وليس لعمل أو دراسة."},{"id":"q3","type":"gap","prompt":"Course start date: ___ October","answer":"14th","max_words":1,"evidence":"so it now starts on 14th October","why_ar":"التاريخ المكتوب في الإعلان (7th October) قديم، وتصحّحه الموظفة: «so it now starts on 14th October»، فالجواب 14th.","accept":["14","fourteenth","14th October"]},{"id":"q4","type":"gap","prompt":"Day of the class: ___ evenings","answer":"Thursday","max_words":1,"evidence":"Then I'll put you down for Thursday","why_ar":"مجموعة الثلاثاء امتلأت وتفضّل المتصلة الخميس، فتقول الموظفة: «Then I'll put you down for Thursday»."},{"id":"q5","type":"gap","prompt":"Class starts at: ___ pm","answer":"7.15","max_words":2,"evidence":"It starts at 7.15 and finishes at 9.15","why_ar":"تظن المتصلة أن الدورة تبدأ في السابعة تمامًا، لكن الموظفة تصحّح: «It starts at 7.15 and finishes at 9.15»، فالبداية 7.15 لا 9.15.","accept":["7.15","7:15","7 15","7.15pm","7.15 pm","seven fifteen","quarter past seven"]},{"id":"q6","type":"gap","prompt":"Room number: ___","answer":"41","max_words":1,"evidence":"I was looking at the wrong column. It's Room 41","why_ar":"تقول الموظفة أولًا Room 14 ثم تصحّح نفسها: «I was looking at the wrong column. It's Room 41»، فالرقم الصحيح 41."},{"id":"q7","type":"gap","prompt":"Course fee (early booking price): ___","answer":"£160","max_words":1,"evidence":"there's an early booking price of £160 if you pay before the end of this month","why_ar":"الرسم العادي £180 لكن سعر الحجز المبكر أقل: «an early booking price of £160»، فالجواب £160.","accept":["160","£160","160 pounds"]},{"id":"q8","type":"gap","prompt":"Cost of the course book: ___","answer":"£28","max_words":1,"evidence":"It costs £28, and you can collect it from reception on the first evening","why_ar":"عند سؤالها عن الكتاب تقول الموظفة: «It costs £28»، ويُستلم من الاستقبال في الأمسية الأولى.","accept":["28","£28","28 pounds"]},{"id":"q9","type":"mcq","prompt":"How will the caller pay for the course?","options":["Online through the website","At reception on Friday","In cash on the first evening","By card over the phone today"],"answer":"B","evidence":"I'll call in on Friday after work and pay at reception","why_ar":"جهاز البطاقة وصفحة الدفع الإلكتروني معطّلان، فتقرّر المتصلة: «I'll call in on Friday after work and pay at reception»."},{"id":"q10","type":"gap","prompt":"Car park entrance: ___ Lane","answer":"Mill","max_words":1,"evidence":"you reach it from Mill Lane","why_ar":"الطريق الأمامي للمبنى مخصص لأصحاب التصاريح فقط، أما موقف السيارات الخلفي فيُدخل إليه من «Mill Lane»."}]},
  {"id":"ls-002","section":2,"title":"Welcome to the Kestrel Science Museum","context_ar":"جولة تعريفية يقدّمها مرشد في متحف علوم جديد: توزيع الطوابق وساعات العمل والقواعد والجولات المصحوبة بمرشد","turns":[{"s":"A","text":"Good morning, everyone, and welcome to the Kestrel Science Museum. My name is Priya, and I'm one of the senior guides. I'll take about ten minutes to explain how the building is laid out before you go off and explore on your own. As we only opened last month, one or two things are still being finished, so thank you for your patience."},{"s":"A","text":"Let's start with the ground floor, where we are now. Straight ahead is the Earth Gallery, where you'll find the giant rotating globe and the earthquake simulator. The café is on your left, and the museum shop is beside the main entrance. A lot of visitors assume that the lifts are next to the shop, but they're actually at the far end of the Earth Gallery, just past the globe."},{"s":"A","text":"Upstairs, the first floor is home to the Energy Gallery, which has hands-on experiments about wind, water and solar power. Our most popular attraction, the Space Dome, is on the second floor. We originally planned to put it on the first floor, but the ceiling there wasn't high enough for the projector, so it had to move. The shows last about thirty minutes and they fill up quickly, so my advice is to reserve a seat at the information desk as soon as you arrive. I'm afraid you can't book online yet, because our website is still being updated."},{"s":"A","text":"The Weather Gallery is also on the second floor, but I'm afraid it's closed at the moment. There was a leak in the roof last month, but that has been repaired. The reason it's still closed is that the engineers are still finishing the tornado display, and we expect it to open by the end of the month."},{"s":"A","text":"Now, a few practical details. We're open from half past nine in the morning until five in the afternoon, Tuesday to Sunday, and we're closed on Mondays except during school holidays. Every Thursday we stay open until 8 in the evening. Those late evenings are much quieter, which many adult visitors prefer, because school groups don't come then."},{"s":"A","text":"There are just a few rules. First, large bags and coats can't be taken into the galleries, so please leave them in the lockers in the basement. You'll need a one pound coin, which you get back when you return the key."},{"s":"A","text":"Second, photography. You're welcome to take photos almost everywhere, as long as you don't use a flash. The only exception is the Space Dome, where no photography at all is permitted, because it would spoil the show for other people."},{"s":"A","text":"Third, touching the exhibits. Most of them are hands-on, but a few are delicate. Please only touch an exhibit if it has a green hand symbol beside it. If there's no symbol, assume that you shouldn't touch it."},{"s":"A","text":"Finally, the tours. We run a free guided tour twice a day, at 11 o'clock and at 2 o'clock, and it leaves from the information desk. It used to be an hour long, but we've shortened it to 45 minutes so that you have more time to explore the galleries yourselves."},{"s":"A","text":"There's also a behind-the-scenes tour, which runs on Wednesdays and Saturdays only. It has to be booked in advance, and places are limited to twelve people. On this tour you'll visit the conservation workshop, where our technicians repair and restore old scientific instruments."},{"s":"A","text":"That's everything from me. If you have any questions, please ask any member of staff in a blue jacket. Enjoy your visit."}],"questions":[{"id":"q1","type":"mcq","prompt":"Where are the lifts?","options":["Beside the museum shop","Near the main entrance","Next to the café","At the far end of the Earth Gallery"],"answer":"D","evidence":"they're actually at the far end of the Earth Gallery, just past the globe","why_ar":"تنفي المرشدة ظنّ الزوار أن المصاعد قرب المتجر: «they're actually at the far end of the Earth Gallery»."},{"id":"q2","type":"mcq","prompt":"What does the guide recommend for visitors who want to see a Space Dome show?","options":["Queue at the dome entrance before the first show","Book through the museum website in advance","Join the free guided tour","Reserve a seat at the information desk when they arrive"],"answer":"D","evidence":"my advice is to reserve a seat at the information desk as soon as you arrive","why_ar":"تنصح المرشدة: «my advice is to reserve a seat at the information desk as soon as you arrive»، والحجز عبر الموقع غير متاح بعد."},{"id":"q3","type":"mcq","prompt":"Why is the Weather Gallery closed at the moment?","options":["A leak has damaged the roof","A display has not been finished yet","It is being used for school groups","It is being moved to the first floor"],"answer":"B","evidence":"the engineers are still finishing the tornado display","why_ar":"تسرّب السقف أُصلح بالفعل، أما سبب الإغلاق فهو: «the engineers are still finishing the tornado display»."},{"id":"q4","type":"gap","prompt":"Late opening (until 8 pm) every ___","answer":"Thursday","max_words":1,"evidence":"Every Thursday we stay open until 8 in the evening","why_ar":"عن ساعات العمل تقول المرشدة: «Every Thursday we stay open until 8 in the evening»، فالجواب Thursday."},{"id":"q5","type":"gap","prompt":"Lockers for large bags are in the ___","answer":"basement","max_words":1,"evidence":"please leave them in the lockers in the basement","why_ar":"في حديثها عن القواعد تطلب ترك الحقائب الكبيرة: «please leave them in the lockers in the basement»."},{"id":"q6","type":"mcq","prompt":"In which part of the museum is photography completely forbidden?","options":["The Earth Gallery","The Energy Gallery","The museum café","The Space Dome"],"answer":"D","evidence":"where no photography at all is permitted","why_ar":"التصوير مسموح تقريبًا في كل مكان بدون فلاش، والاستثناء الوحيد هو Space Dome حيث «no photography at all is permitted»."},{"id":"q7","type":"mcq","prompt":"When may visitors touch an exhibit?","options":["Only on the first floor","Whenever it is not behind glass","Only when it has a green hand symbol","Only when a guide is nearby"],"answer":"C","evidence":"Please only touch an exhibit if it has a green hand symbol beside it","why_ar":"القاعدة الثالثة: «Please only touch an exhibit if it has a green hand symbol beside it»، وإن لم يوجد رمز فلا يُلمس."},{"id":"q8","type":"gap","prompt":"The free guided tour lasts ___ minutes.","answer":"45","max_words":1,"evidence":"It used to be an hour long, but we've shortened it to 45 minutes","why_ar":"كانت الجولة ساعة كاملة سابقًا، لكن المرشدة تقول: «we've shortened it to 45 minutes»، فالجواب 45."},{"id":"q9","type":"mcq","prompt":"On which days does the behind-the-scenes tour run?","options":["Tuesdays and Thursdays","Fridays and Sundays","Every day except Monday","Wednesdays and Saturdays"],"answer":"D","evidence":"which runs on Wednesdays and Saturdays only","why_ar":"عن جولة «خلف الكواليس» تقول المرشدة: «which runs on Wednesdays and Saturdays only»."},{"id":"q10","type":"gap","prompt":"The behind-the-scenes tour visits the conservation ___, where old instruments are repaired.","answer":"workshop","max_words":1,"evidence":"On this tour you'll visit the conservation workshop","why_ar":"تذكر المرشدة ما تشمله الجولة: «On this tour you'll visit the conservation workshop»، حيث تُرمَّم الأجهزة القديمة."}]},
  {"id":"ls-003","section":3,"title":"Choosing a focus for an urban planning project","context_ar":"نقاش بين طالبين ومشرفة أكاديمية حول مشروع جامعي في التخطيط العمراني: اختيار المنطقة وطريقة جمع المعلومات وتوزيع المهام","turns":[{"s":"A","text":"Come in, both of you, and take a seat. So, how are you getting on with the urban planning project?"},{"s":"B","text":"Quite well, thanks, Doctor Hartley, but we haven't actually decided where to focus yet. I think we both like the idea of the town centre, don't we, Jonas?"},{"s":"C","text":"Well, I did at first, but I've changed my mind. So many students have written about pedestrian streets and shopping areas that I doubt we'd have anything new to say."},{"s":"B","text":"That's true, but at least we know where to find the data. If we choose somewhere less familiar, we might end up with very little to work from."},{"s":"A","text":"That's a fair point, Maya, though I'd say it's a risk worth taking. Have you considered the riverside district? The old warehouses beside the canal are being turned into flats, and nobody has really looked at how the area will cope."},{"s":"B","text":"Now that you mention it, that could work really well. It's changing so fast, and I'd love to find out what residents think about it. I'm quite excited about it, actually."},{"s":"C","text":"I'm happy with that as well. Let's go for the riverside district, then."},{"s":"A","text":"Good. There's one thing I'd advise, though. Keep the study area small. Last year a group tried to cover the entire district and ended up with masses of information but hardly any analysis. Three or four streets around the old market square would be enough."},{"s":"C","text":"That makes sense. Now, for collecting information, I'd like to use an online questionnaire. We could post the link in the residents' groups."},{"s":"B","text":"I'm not sure about that, Jonas. The people who fill in online surveys are usually the ones who already have strong opinions. I'd rather speak to people face to face, on the street."},{"s":"A","text":"I'd agree with Maya. Online response rates are often disappointing, and in person you can ask follow-up questions."},{"s":"C","text":"All right, I'll give way on that. Short street interviews it is."},{"s":"B","text":"How many people should we aim to speak to? I was thinking of 100."},{"s":"A","text":"That's far too ambitious for two people working during term time."},{"s":"C","text":"Even so, 20 would be too few to tell us anything."},{"s":"A","text":"I think 40 is a realistic target, and I'd be happy with that."},{"s":"B","text":"Fine, then. We'll aim for that."},{"s":"A","text":"Now, a word about your recommendations. Some groups in the past have put forward ideas that nobody could ever build. Whatever you propose, it should be something the council could realistically carry out within about five years. The markers will reward practical ideas more than perfect ones."},{"s":"B","text":"That's useful to know. What about the presentation? I thought I could talk through the interview results, and Jonas could present the proposals."},{"s":"C","text":"Actually, I'd prefer it the other way round. I'm more comfortable with the figures, and Maya's much better at explaining design ideas."},{"s":"B","text":"Fair enough. I don't mind swapping."},{"s":"A","text":"Good. Now, timing. I'd like to see a short outline of your report before you go much further. Would Wednesday suit you?"},{"s":"B","text":"That's a bit soon, to be honest. Could we have until the end of the week?"},{"s":"A","text":"Of course. I'm at a conference until Thursday anyway, so send it to me by Friday."},{"s":"C","text":"And I suppose the first thing we ought to do is see the area for ourselves."},{"s":"B","text":"Yes. Why don't we spend Saturday morning there, taking photographs and counting how many people use the paths?"},{"s":"C","text":"Fine by me. I'll bring my camera."},{"s":"A","text":"Excellent. It sounds as though you have a plan. Come and see me again once you've done your first round of interviews."}],"questions":[{"id":"q1","type":"mcq","prompt":"Why has Jonas changed his mind about the town centre?","options":["It has been written about so often that there would be little new to say","There is not enough information available about it","It is too large an area for a student project","The council is already redesigning it"],"answer":"A","evidence":"So many students have written about pedestrian streets and shopping areas that I doubt we'd have anything new to say","why_ar":"يقول جوناس: «So many students have written about pedestrian streets... that I doubt we'd have anything new to say»، أما مايا فهي التي ترى أن بيانات وسط المدينة متوفرة."},{"id":"q2","type":"mcq","prompt":"What attracts Maya to the riverside district?","options":["It is developing very quickly","It has excellent transport links","It is close to the university","It has many historic buildings"],"answer":"A","evidence":"that could work really well. It's changing so fast","why_ar":"تقول مايا عن الحي: «It's changing so fast»، أي أنه يتطور بسرعة، ولم يُذكر التاريخ أو المواصلات أو القرب من الجامعة."},{"id":"q3","type":"gap","prompt":"The students decide to study the ___ district.","answer":"riverside","max_words":1,"evidence":"Let's go for the riverside district","why_ar":"بعد اقتراح المشرفة يحسم جوناس القرار: «Let's go for the riverside district»، فالجواب riverside."},{"id":"q4","type":"mcq","prompt":"What does Doctor Hartley advise about the study area?","options":["Include the town centre as a comparison","Cover the whole district so that areas can be compared","Concentrate on a small number of streets","Choose the busiest roads in the town"],"answer":"C","evidence":"Three or four streets around the old market square would be enough","why_ar":"تنصح بتصغير نطاق الدراسة: «Three or four streets around the old market square would be enough»، وتحذّر من مجموعة غطّت الحي كله."},{"id":"q5","type":"mcq","prompt":"How do the students decide to collect information from residents?","options":["By studying existing council reports","By sending an online questionnaire","By interviewing people in the street","By combining questionnaires with interviews"],"answer":"C","evidence":"I'll give way on that. Short street interviews it is","why_ar":"بعد اعتراض مايا وتأييد المشرفة يتراجع جوناس: «I'll give way on that. Short street interviews it is»."},{"id":"q6","type":"gap","prompt":"Number of interviews they will aim for: ___","answer":"40","max_words":1,"evidence":"I think 40 is a realistic target","why_ar":"مايا اقترحت 100 وجوناس رأى أن 20 قليل، أما المشرفة فتحسم: «I think 40 is a realistic target»."},{"id":"q7","type":"mcq","prompt":"What does Doctor Hartley say about the students' recommendations?","options":["They should be realistic enough for the council to carry out","They should be based on an example from abroad","They should avoid changes to traffic","They should be as ambitious as possible"],"answer":"A","evidence":"it should be something the council could realistically carry out within about five years","why_ar":"تطلب مقترحات عملية: «it should be something the council could realistically carry out within about five years»."},{"id":"q8","type":"mcq","prompt":"Who will present the proposals in the final presentation?","options":["Jonas","Maya","Dr Hartley","Maya and Jonas together"],"answer":"B","evidence":"I'd prefer it the other way round. I'm more comfortable with the figures, and Maya's much better at explaining design ideas","why_ar":"يطلب جوناس عكس الاقتراح لأنه أرتاح مع الأرقام و«Maya's much better at explaining design ideas»، وتوافق مايا، فهي من يعرض المقترحات."},{"id":"q9","type":"gap","prompt":"The tutor wants to receive the outline by ___","answer":"Friday","max_words":1,"evidence":"I'm at a conference until Thursday anyway, so send it to me by Friday","why_ar":"اقترحت المشرفة الأربعاء فطلبت مايا مهلة أطول، فتقول: «so send it to me by Friday»، والخميس هو يوم عودتها فقط."},{"id":"q10","type":"mcq","prompt":"What do the students agree to do first?","options":["Contact the council's planning office","Write the introduction to the report","Interview residents on Monday","Spend a morning at the site on Saturday"],"answer":"D","evidence":"Why don't we spend Saturday morning there, taking photographs and counting how many people use the paths","why_ar":"تقترح مايا: «Why don't we spend Saturday morning there, taking photographs and counting...»، ويوافق جوناس بقوله «Fine by me»."}]},
  {"id":"ls-004","section":4,"title":"How glaciers shape valleys","context_ar":"محاضرة جامعية في الجغرافيا الطبيعية عن كيفية تشكيل الأنهار الجليدية للوديان الجبلية","turns":[{"s":"A","text":"Good morning, everyone. Today I want to look at how glaciers shape mountain valleys. My aim is to show you that a landscape can be read almost like a book, if you know what to look for. Many of the dramatic valleys that walkers and photographers admire today were carved during the last ice age, which ended more than 10,000 years ago, and the evidence they left behind is still very clear."},{"s":"A","text":"Let's begin with how a glacier is created. In cold mountain regions, more snow falls in winter than melts in summer, so the snow builds up year after year. The lower layers are squeezed by the snow above them, and gradually they turn into solid ice. Once the mass of ice is thick enough, it begins to flow slowly downhill under its own weight. Please don't picture a frozen block. The ice is moving, usually by no more than a few metres a day, but it never stops."},{"s":"A","text":"Now, before the ice arrived, most of these valleys had been cut by rivers. A river valley typically has a V-shaped cross-section, because the water mainly cuts downwards. A glacier is very different. It is far wider and heavier than a river, so it wears away the sides of the valley as well as deepening it. The result is a valley with steep sides and a wide, flat valley floor, and the whole cross-section looks more like the letter U."},{"s":"A","text":"How does the ice actually do this? There are two main processes. The first is called plucking. Meltwater seeps into cracks in the bedrock and freezes there, so the ice grips the rock. As the glacier moves forward, it pulls whole blocks of stone away from the valley wall. The second process is abrasion. Rock fragments trapped in the base of the ice act like sandpaper and scrape the surface beneath. This grinding produces a very fine powder, called rock flour, which is washed out by meltwater and often gives glacial streams and lakes a milky, pale blue colour."},{"s":"A","text":"Next, the side valleys. Large valleys often have smaller valleys joining them. During the ice age these smaller valleys held smaller glaciers, which could not cut down as deeply as the main one. So when the ice melted, the side valleys were left high above the main valley, and we call them hanging valleys. Streams that flow out of them often drop as waterfalls, which is why you so often find waterfalls in glacial landscapes."},{"s":"A","text":"Glaciers don't only remove material, they deposit it as well. As the ice melts, it drops everything it has been carrying. Long ridges of rock and debris left at the edges and the front of a glacier are called moraines. Sometimes the ice carries an enormous boulder many kilometres and leaves it sitting where the local rock is completely different. These stranded boulders are known as erratics, and they are one of the simplest clues that ice was once present."},{"s":"A","text":"Finally, a word about the coast. In some places, glacial valleys run down to the sea. When the ice melted and sea levels rose, the water flooded the deepest part of the valley and created a long, narrow, steep-sided inlet. In Norway and New Zealand, for example, we call this a fjord."},{"s":"A","text":"To sum up, glaciers widen, deepen and straighten valleys, and then leave their own deposits behind. Next week we will look at the shapes of the mountain peaks above the valleys. In the meantime, please read the first two chapters of the course text and bring any questions you have about today's topics."}],"questions":[{"id":"q1","type":"gap","prompt":"The last ice age ended more than ___ years ago.","answer":"10,000","max_words":2,"evidence":"which ended more than 10,000 years ago","why_ar":"في مقدمة المحاضرة: «the last ice age, which ended more than 10,000 years ago»، فالجواب 10,000.","accept":["10000","10 000","ten thousand"]},{"id":"q2","type":"gap","prompt":"When the ice is thick enough, it flows downhill under its own ___.","answer":"weight","max_words":1,"evidence":"it begins to flow slowly downhill under its own weight","why_ar":"عند شرح تكوّن النهر الجليدي: «it begins to flow slowly downhill under its own weight»."},{"id":"q3","type":"gap","prompt":"A glacial valley has steep sides and a wide, flat valley ___.","answer":"floor","max_words":1,"evidence":"a valley with steep sides and a wide, flat valley floor","why_ar":"في مقارنته بوادي النهر ذي الشكل V يقول: «a valley with steep sides and a wide, flat valley floor»."},{"id":"q4","type":"gap","prompt":"Process 1: ice freezes onto rock and pulls blocks away, called ___.","answer":"plucking","max_words":1,"evidence":"There are two main processes. The first is called plucking","why_ar":"العملية الأولى من عمليتي التآكل: «The first is called plucking»، حيث يمسك الجليد الصخر ويقتلع كتلًا منه."},{"id":"q5","type":"gap","prompt":"Process 2: stones trapped in the ice scrape the surface beneath, called ___.","answer":"abrasion","max_words":1,"evidence":"The second process is abrasion. Rock fragments trapped in the base of the ice act like sandpaper","why_ar":"العملية الثانية: «The second process is abrasion»، وتشبّه المحاضِرة الشظايا الصخرية العالقة بورق الصنفرة."},{"id":"q6","type":"gap","prompt":"Abrasion produces a very fine powder known as ___.","answer":"rock flour","max_words":2,"evidence":"This grinding produces a very fine powder, called rock flour","why_ar":"عن نتاج الطحن: «a very fine powder, called rock flour»، وهو يمنح مياه الذوبان لونًا حليبيًا."},{"id":"q7","type":"gap","prompt":"Smaller side valleys that end high above the main valley are called ___ valleys.","answer":"hanging","max_words":1,"evidence":"the side valleys were left high above the main valley, and we call them hanging valleys","why_ar":"الأودية الجانبية الأقل عمقًا: «we call them hanging valleys»، أي الأودية المعلّقة."},{"id":"q8","type":"gap","prompt":"Ridges of debris dumped at the edge or front of a glacier are called ___.","answer":"moraines","max_words":1,"evidence":"Long ridges of rock and debris left at the edges and the front of a glacier are called moraines","why_ar":"عن الترسبات: «Long ridges of rock and debris... are called moraines»، أي الركامات الجليدية.","accept":["moraine"]},{"id":"q9","type":"gap","prompt":"Large boulders left far from their original source are known as ___.","answer":"erratics","max_words":1,"evidence":"These stranded boulders are known as erratics","why_ar":"الصخور الضخمة المنقولة لمسافات بعيدة: «These stranded boulders are known as erratics».","accept":["erratic"]},{"id":"q10","type":"gap","prompt":"A glacial valley flooded by the sea is called a ___ .","answer":"fjord","max_words":1,"evidence":"In Norway and New Zealand, for example, we call this a fjord","why_ar":"في حديثه عن السواحل: «we call this a fjord»، أي خليج ضيق عميق تكوّن بفيضان البحر على وادٍ جليدي.","accept":["fjord","fiord"]}]},
  {"id":"ls-005","section":1,"title":"Joining the public library","context_ar":"محادثة عند مكتب الاستقبال في مكتبة عامة بين موظفة ومتقدّم جديد يريد الاشتراك واستعارة الكتب","turns":[{"s":"A","text":"Good morning, Elmfield Central Library. How can I help you?"},{"s":"B","text":"Hello, I've just moved to the area and I'd like to join the library, please. Do I need to make an appointment?"},{"s":"A","text":"No, not at all. You can join here at the desk and it only takes a few minutes. I'll fill in the form as we go. Could I have your surname first, please?"},{"s":"B","text":"Yes, of course, it's Ashworth. That's A-S-H-W-O-R-T-H."},{"s":"A","text":"Thank you. And your address?"},{"s":"B","text":"It's Flat 3, 27 Quillfield Road. That's Q-U-I-L-L-F-I-E-L-D."},{"s":"A","text":"Lovely. And the postcode?"},{"s":"B","text":"It's KT6 4BQ. No, sorry, it's KT8 4BQ. I always get that wrong, because I've only lived there for a week."},{"s":"A","text":"KT8 4BQ, thank you. Now, I need to see one document as proof of your address. A utility bill or a letter from your employer would be fine."},{"s":"B","text":"Oh dear, I haven't got either of those with me. I do have my tenancy agreement, though. Would that do?"},{"s":"A","text":"Yes, that's perfectly acceptable, as long as it shows your name and the address. Now, is there anything in particular you'll be using the library for? Some members join for the computers, others for the reading groups, and a lot of families come for the children's activities on Saturday mornings."},{"s":"B","text":"Well, mainly somewhere quiet to study, actually. I'm starting a part-time degree in October and my flat is rather small. I've got my own laptop, so I won't need the computers, and I'm too busy for reading groups at the moment. I'll probably carry on buying my novels."},{"s":"A","text":"That makes sense. Right, as a member you can borrow up to 8 items at a time. Sorry, I mean 10. The limit for children under sixteen is 8. That includes books, audiobooks and DVDs."},{"s":"B","text":"And how long can I keep them?"},{"s":"A","text":"Books can be kept for 3 weeks, but DVDs only for 1 week. If you bring anything back late, there's a charge of 25 pence a day for each item."},{"s":"B","text":"That sounds fair. What about the card itself? Is there a charge for that?"},{"s":"A","text":"Membership is free, but there is a charge for the plastic card. It was £2.50 last year, but it went up to £4 in January."},{"s":"B","text":"That's fine. Can I pay now? And is it possible to renew books by email, if I'm busy?"},{"s":"A","text":"You can pay here at the desk, and I'll print the card straight away. As for renewing, not by email, I'm afraid, but you can do it by phone, or you can use the library app, which is quicker."},{"s":"B","text":"Lovely. One last thing, where is the quiet study area?"},{"s":"A","text":"The ground floor is for fiction and the children's library, and the study area is up on the first floor, just past the local history section. There's also a small room in the basement, but that's only for group bookings."},{"s":"B","text":"Perfect, thank you."},{"s":"A","text":"Your card will be ready in about five minutes, so why don't you have a look round while I print it? Oh, and we're open until 8 o'clock on Thursdays, but only until 5 on the other weekdays."},{"s":"B","text":"Thanks very much, I will."}],"questions":[{"id":"q1","type":"gap","prompt":"Surname: ___","answer":"Ashworth","max_words":1,"evidence":"of course, it's Ashworth. That's A-S-H-W-O-R-T-H","why_ar":"ينطق B الاسم ثم يهجّيه: «it's Ashworth. That's A-S-H-W-O-R-T-H»، فالإجابة Ashworth."},{"id":"q2","type":"gap","prompt":"Address: Flat 3, 27 ___ Road","answer":"Quillfield","max_words":1,"evidence":"Flat 3, 27 Quillfield Road. That's Q-U-I-L-L-F-I-E-L-D","why_ar":"اسم الشارع يُنطق ثم يُهجّى حرفًا حرفًا: «27 Quillfield Road. That's Q-U-I-L-L-F-I-E-L-D»، فالإجابة Quillfield."},{"id":"q3","type":"gap","prompt":"Postcode: ___","answer":"KT8 4BQ","max_words":2,"evidence":"No, sorry, it's KT8 4BQ. I always get that wrong","why_ar":"قال B أولًا KT6 4BQ ثم صحّح نفسه فورًا: «No, sorry, it's KT8 4BQ»، فالرمز المعتمد هو KT8 4BQ."},{"id":"q4","type":"gap","prompt":"Document brought as proof of address: ___","answer":"tenancy agreement","max_words":2,"evidence":"I do have my tenancy agreement, though","why_ar":"عرضت الموظفة فاتورة خدمات أو خطابًا من جهة العمل، لكن B ليس معه أيٌّ منهما: «I do have my tenancy agreement, though»، فالمستند هو tenancy agreement."},{"id":"q5","type":"mcq","prompt":"Why does B want to join the library?","options":["To use the library computers","To borrow novels","To have a quiet place to study","To take part in reading groups"],"answer":"C","evidence":"mainly somewhere quiet to study, actually","why_ar":"قال B إنه يريد المكتبة أساسًا للدراسة: «mainly somewhere quiet to study, actually». ونفى حاجته للحواسيب ولمجموعات القراءة، وسيستمر في شراء رواياته."},{"id":"q6","type":"gap","prompt":"Maximum number of items an adult member can borrow at one time: ___","answer":"10","max_words":1,"evidence":"you can borrow up to 8 items at a time. Sorry, I mean 10","why_ar":"قالت الموظفة أولًا 8 ثم صحّحت: «Sorry, I mean 10». والرقم 8 هو حدّ الأطفال دون السادسة عشرة فقط."},{"id":"q7","type":"gap","prompt":"Books can be borrowed for ___ weeks","answer":"3","max_words":1,"evidence":"Books can be kept for 3 weeks","why_ar":"مدة إعارة الكتب «Books can be kept for 3 weeks»، أما أقراص DVD فأسبوع واحد فقط."},{"id":"q8","type":"gap","prompt":"Charge for the plastic card: £___","answer":"4","max_words":1,"evidence":"it went up to £4 in January","why_ar":"السعر القديم كان 2.50 جنيه، لكنها أوضحت أنه ارتفع: «it went up to £4 in January»، فالرسوم الحالية 4."},{"id":"q9","type":"gap","prompt":"Items can be renewed by phone or by using the library ___","answer":"app","max_words":1,"evidence":"you can use the library app, which is quicker","why_ar":"رفضت الموظفة التجديد بالبريد الإلكتروني وذكرت الهاتف، ثم قالت: «you can use the library app, which is quicker»، فالإجابة app.","accept":["application"]},{"id":"q10","type":"mcq","prompt":"Where is the quiet study area?","options":["Next to the main entrance","In the basement","On the first floor, past the local history section","On the ground floor, beside the children's library"],"answer":"C","evidence":"the study area is up on the first floor, just past the local history section","why_ar":"قالت الموظفة: «the study area is up on the first floor, just past the local history section». الطابق الأرضي للروايات والأطفال، والقبو لحجوزات المجموعات فقط."}]},
  {"id":"ls-006","section":2,"title":"A new city bicycle-hire scheme","context_ar":"إعلان من موظف في مجلس مدينة افتراضية عن إطلاق مشروع جديد لتأجير الدراجات الهوائية: المحطات والأسعار وقواعد السلامة","turns":[{"s":"A","text":"Good morning, everyone, and thank you for coming to the launch of Larkmoor's new bicycle-hire scheme. I'm the council's transport officer, and for the next few minutes I'd like to explain how the scheme will work before it opens to the public at the beginning of next month."},{"s":"A","text":"I'll begin with the stations. When we first drew up the plans, we hoped to open with 40 docking stations across the city. Unfortunately, building work along Mill Street has caused delays, so only 30 will be ready on opening day. You'll find them at the main railway station, the university, the hospital, Riverside Park and around Market Square, as well as at a number of smaller sites in between. The one area that will have to wait is the north of the city. Elm Park will not get its station until the second phase, because the new cycle lane that leads there isn't finished yet. We expect to open the remaining stations by the end of the year."},{"s":"A","text":"Now, let me tell you about the bicycles. There will be 450 of them, all painted bright green so that they're easy to recognise. Each one has a basket at the front, three gears and lights that switch on automatically as soon as you start pedalling. To unlock a bicycle, you first need to register with the scheme's app. Once you've done that, you simply scan the code on the handlebars. People often assume the code is on the frame, but we've put it on the handlebars because the frame gets dirty and scratched far too quickly. I should add that the app won't be available until the launch day, so please don't try to download it yet."},{"s":"A","text":"Let me move on to prices. Everybody gets the first 30 minutes of every journey free, and after that you pay £1 for each extra half hour. If you plan to cycle regularly, though, you'll probably prefer an annual membership, which costs £40 and lets you ride for up to 45 minutes free every time. Students and people over 65 pay half price for membership, which is £20. We did think about offering a day pass as well, but we decided it would make the system too complicated."},{"s":"A","text":"Now, a few safety rules, which are very important. Riders must be at least 16 years old, and only one person may ride each bicycle, so no passengers, I'm afraid. Pavements are for pedestrians. You may ride on a pavement only where a sign shows that the path is shared with walkers. We won't provide helmets, but we strongly advise you to bring your own, particularly if you're cycling on busier roads. Please also remember that it's your responsibility to lock the bicycle properly into a docking point. If you leave a bicycle outside a station, you'll be charged a fee of £15. It was £10 during the trial period, but we've increased it because too many bicycles were being left in the street."},{"s":"A","text":"If you find that a bicycle is faulty, perhaps because of a flat tyre or a loose seat, please don't just leave it. Take it back to the nearest station if it's safe to ride, and press the red button on the docking point. That tells our engineers that the bicycle must be taken out of service. If it isn't safe to ride, you can call the helpline instead, and a van will collect it."},{"s":"A","text":"Finally, I'd like to invite you all to a free guided ride at Riverside Park at 10 o'clock on Saturday morning. We'll bring a number of bicycles, so that you can try them before the official opening. Places are limited, so to take part, please put your name on the list at the library desk before you leave today. You won't be able to book through the app, because it won't be ready until the launch. Thank you very much for listening, and I'll be happy to take any questions now."}],"questions":[{"id":"q1","type":"gap","prompt":"Number of docking stations on opening day: ___","answer":"30","max_words":1,"evidence":"so only 30 will be ready on opening day","why_ar":"كان المخطط 40 محطة لكن أعمال البناء أخّرت بعضها: «so only 30 will be ready on opening day»، فالإجابة 30."},{"id":"q2","type":"mcq","prompt":"Which area will not have a station when the scheme opens?","options":["The university","Elm Park","Market Square","Riverside Park"],"answer":"B","evidence":"Elm Park will not get its station until the second phase","why_ar":"قال المتحدث: «Elm Park will not get its station until the second phase»، أما بقية المواقع فمذكورة بين المحطات الجاهزة."},{"id":"q3","type":"gap","prompt":"To unlock a bicycle, scan the code on the ___","answer":"handlebars","max_words":1,"evidence":"you simply scan the code on the handlebars","why_ar":"الرمز موجود على المقود وليس على الهيكل: «you simply scan the code on the handlebars»، فالإجابة handlebars.","accept":["handlebar","handle bars"]},{"id":"q4","type":"mcq","prompt":"What is the advantage of an annual membership?","options":["Extra stations can be used at weekends","Each journey can be longer before any charge is made","A bicycle is reserved at the nearest station","Helmets are provided free of charge"],"answer":"B","evidence":"lets you ride for up to 45 minutes free every time","why_ar":"ميزة العضوية السنوية: «lets you ride for up to 45 minutes free every time»، أي فترة مجانية أطول (45 دقيقة بدل 30) في كل رحلة."},{"id":"q5","type":"gap","prompt":"Annual membership price for students: £___","answer":"20","max_words":1,"evidence":"Students and people over 65 pay half price for membership, which is £20","why_ar":"العضوية السنوية 40 جنيهًا وللطلاب نصف السعر: «half price for membership, which is £20»، فالإجابة 20."},{"id":"q6","type":"mcq","prompt":"When may riders use a pavement?","options":["Only when they are travelling to a docking station","Only where a sign shows that the path is shared with pedestrians","Whenever the road is busy","At any time, if they ride slowly"],"answer":"B","evidence":"You may ride on a pavement only where a sign shows that the path is shared with walkers","why_ar":"قال المتحدث: «You may ride on a pavement only where a sign shows that the path is shared with walkers»، أي بوجود لافتة تشير إلى مسار مشترك فقط."},{"id":"q7","type":"mcq","prompt":"What does the speaker say about helmets?","options":["They can be hired at every station.","They are not allowed on the scheme.","Riders are advised to bring their own.","Only riders under 18 must wear one."],"answer":"C","evidence":"We won't provide helmets, but we strongly advise you to bring your own","why_ar":"قال المتحدث: «We won't provide helmets, but we strongly advise you to bring your own»، أي ينصح الراكب بإحضار خوذته بنفسه."},{"id":"q8","type":"gap","prompt":"Fee for leaving a bicycle outside a station: £___","answer":"15","max_words":1,"evidence":"you'll be charged a fee of £15","why_ar":"الغرامة كانت 10 في الفترة التجريبية ثم رُفعت: «you'll be charged a fee of £15»، فالإجابة 15."},{"id":"q9","type":"mcq","prompt":"What should a rider do with a faulty bicycle that is safe to ride?","options":["Dock it at a station and press a button","Phone the helpline at once","Leave it by the roadside for a van to collect","Report the fault in the app"],"answer":"A","evidence":"Take it back to the nearest station if it's safe to ride, and press the red button on the docking point","why_ar":"قال المتحدث: «Take it back to the nearest station if it's safe to ride, and press the red button on the docking point»؛ الاتصال بالخط الساخن للدراجة غير الآمنة فقط."},{"id":"q10","type":"mcq","prompt":"How can people reserve a place on the guided ride?","options":["By using the scheme's app","By arriving at the park on the day","By adding their name to a list at the library","By phoning the council helpline"],"answer":"C","evidence":"please put your name on the list at the library desk before you leave today","why_ar":"قال المتحدث: «please put your name on the list at the library desk before you leave today»، ونفى إمكان الحجز عبر التطبيق قبل الإطلاق."}]},
  {"id":"ls-007","section":3,"title":"Planning a psychology survey report","context_ar":"نقاش بين ثلاثة طلاب (مايا وكالوم وناديا) حول تصميم استبيان صغير عن النوم واستخدام الهاتف ونتائجه لواجب في مقرر علم النفس","turns":[{"s":"A","text":"Okay, Nadia, Callum, shall we make a start? We've got all the questionnaires back from the sleep survey, and the report is due at the end of next week, so we really need to decide how we're going to write it up. I thought we could begin with how we designed the survey, because the report needs a section on its limitations."},{"s":"B","text":"Good idea, Maya. The thing that worries me most is the sample. We only got sixty-two responses, and nearly all of them came from the first-year psychology lecture, because that's where we handed out the questionnaires."},{"s":"C","text":"I agree it's a weakness, Callum, but I don't think it's a disaster. The assignment only asks for a small survey. What the tutor wants is for us to recognise the problem, not to solve it. We just need to say that it was a convenience sample and that the findings may not apply to students on other courses."},{"s":"B","text":"Fair enough. And at least almost everybody in the room filled it in, so the response rate was high."},{"s":"A","text":"True. What about the wording of the questions? Do you remember the pilot? When we tried the questionnaire on five of our friends, one of them said she didn't understand question four."},{"s":"C","text":"Yes, that was the one about how long you use your phone late in the evening. She said that the word late could mean anything, from six o'clock to midnight."},{"s":"A","text":"Right, so we changed it to the hour before you go to sleep, which is much clearer. I think that's worth mentioning in the report, because it shows why piloting matters."},{"s":"B","text":"Definitely. Now, something I'm still not sure about is the answer scale. I used five points for sleep quality, from very poor to very good, but I wonder whether seven points would have given us more detail."},{"s":"A","text":"Maybe, but with a sample this small, seven options would spread the answers too thinly. I think five was the right choice."},{"s":"B","text":"Okay, you've convinced me. We can explain that in the methods section."},{"s":"C","text":"And on ethics, we didn't collect any names, and the first page had a consent statement, so I think we're covered there."},{"s":"A","text":"Yes. Right, let's look at the results. The average sleep rating across all sixty-two people was 3.1 out of 5, and the average time spent on the phone in the last hour before bed was about forty minutes."},{"s":"B","text":"And there's a clear pattern, isn't there, Maya? The more time people spent on their phones, the lower they rated their sleep. I think we can say that phones are damaging students' sleep."},{"s":"C","text":"Hmm, I wouldn't go that far, Callum. All we've shown is that the two things go together. It could be that students who are stressed about their exams both stay on their phones and sleep badly. We can't prove that one causes the other."},{"s":"A","text":"Nadia's right. A correlation only tells us that two things are related, and ours was only weak anyway. We'd need an experiment to show cause."},{"s":"B","text":"All right, I take the point. How about we write that heavy phone use is associated with lower ratings, instead of saying that it causes them?"},{"s":"A","text":"Perfect. Now, for the presentation next week, I think we should use a graph rather than a table, because sixty-two rows of numbers would be unreadable."},{"s":"C","text":"Yes, a scatter graph would show the pattern straight away. But the tutor said we have to include the raw data somewhere."},{"s":"A","text":"We can put the table in an appendix at the end of the report. Now, shall we divide up the writing? I'll do the introduction and draw the graph."},{"s":"B","text":"I'll take the discussion, since I'm the one who got so excited about the conclusion."},{"s":"C","text":"Actually, Callum, would you mind if I did the discussion? I'd like to practise writing about the limitations. You designed the questionnaire, so you could do the methods."},{"s":"B","text":"No problem, that makes sense. I'll do the methods, then."},{"s":"A","text":"Great. Let's aim to have a full draft by Wednesday, so that we have time to check everything before the deadline on Friday."},{"s":"C","text":"Fine by me. I'll send you both my notes tonight."}],"questions":[{"id":"q1","type":"mcq","prompt":"According to Callum, what is the main weakness of the sample?","options":["Very few people completed the questionnaire fully.","Most respondents were in their final year.","Nearly all the participants came from the same lecture.","The participants were chosen by the tutor."],"answer":"C","evidence":"nearly all of them came from the first-year psychology lecture","why_ar":"قال Callum: «nearly all of them came from the first-year psychology lecture»، أي أن أغلب المشاركين من محاضرة واحدة."},{"id":"q2","type":"mcq","prompt":"What does Nadia think the group should do about this weakness?","options":["Collect more responses from other courses before writing","Ask the tutor to change the topic","Explain it in the report as a limitation","Leave out the results from the psychology lecture"],"answer":"C","evidence":"We just need to say that it was a convenience sample and that the findings may not apply to students on other courses","why_ar":"قالت Nadia: «We just need to say that it was a convenience sample...»، فيكفي ذكرها كقيد في التقرير لأن المطلوب إدراك المشكلة لا حلّها."},{"id":"q3","type":"gap","prompt":"In the pilot, a friend found the word '___' in question 4 unclear.","answer":"late","max_words":1,"evidence":"She said that the word late could mean anything","why_ar":"قالت صديقتهم في التجربة الأولية: «She said that the word late could mean anything»، فالكلمة هي late."},{"id":"q4","type":"mcq","prompt":"Why does Maya think a five-point scale is enough?","options":["The friends in the pilot preferred it","A longer scale would divide the answers too much in a small sample","The tutor requires five points","Respondents found longer scales confusing"],"answer":"B","evidence":"with a sample this small, seven options would spread the answers too thinly","why_ar":"قالت Maya: «with a sample this small, seven options would spread the answers too thinly»، أي أن العينة الصغيرة لا تتحمّل خيارات أكثر."},{"id":"q5","type":"gap","prompt":"Average sleep rating: ___ out of 5","answer":"3.1","max_words":2,"evidence":"The average sleep rating across all sixty-two people was 3.1 out of 5","why_ar":"قالت Maya: «The average sleep rating across all sixty-two people was 3.1 out of 5»، فالإجابة 3.1."},{"id":"q6","type":"mcq","prompt":"What reason does Nadia give for doubting that phones damage sleep?","options":["Another factor could explain both phone use and poor sleep","The questionnaire contained confusing questions","Sleep cannot be measured with a questionnaire","Students were not honest about their phone use"],"answer":"A","evidence":"students who are stressed about their exams both stay on their phones and sleep badly","why_ar":"قالت Nadia: «students who are stressed about their exams both stay on their phones and sleep badly»، أي أن عاملًا ثالثًا (التوتر) قد يفسّر الظاهرتين."},{"id":"q7","type":"mcq","prompt":"How does Maya describe the correlation in their data?","options":["It does not exist","It is strong enough to show a cause","It is stronger than they expected","It is only weak"],"answer":"D","evidence":"A correlation only tells us that two things are related, and ours was only weak anyway","why_ar":"قالت Maya: «and ours was only weak anyway»، أي أن الارتباط في بياناتهم ضعيف فقط."},{"id":"q8","type":"mcq","prompt":"Where will the table of raw data be placed?","options":["On a slide in the presentation","In the methods section","On the tutor's website","In an appendix"],"answer":"D","evidence":"We can put the table in an appendix at the end of the report","why_ar":"قالت Maya: «We can put the table in an appendix at the end of the report»، بينما يُستخدم الرسم البياني في العرض."},{"id":"q9","type":"mcq","prompt":"Which section of the report will Callum write?","options":["The results","The introduction","The methods","The discussion"],"answer":"C","evidence":"No problem, that makes sense. I'll do the methods, then","why_ar":"اقترح Callum أولًا كتابة الـ discussion، لكن Nadia طلبت تبديلها فوافق: «I'll do the methods, then»، فالإجابة C."},{"id":"q10","type":"gap","prompt":"Full draft to be finished by ___","answer":"Wednesday","max_words":1,"evidence":"Let's aim to have a full draft by Wednesday","why_ar":"قالت Maya: «Let's aim to have a full draft by Wednesday»؛ أما يوم الجمعة Friday فهو موعد التسليم النهائي."}]},
  {"id":"ls-008","section":4,"title":"How honeybees communicate and organise their colony","context_ar":"محاضرة أكاديمية عن تنظيم مستعمرة النحل وتقسيم العمل بين أفرادها وطرق التواصل بينها","turns":[{"s":"A","text":"Good afternoon, everyone. Today I'd like to talk about honeybees, and in particular how a colony containing tens of thousands of individuals manages to behave almost like a single organism. I'll begin with the different members of the colony, then look at how the work is divided between them, and finish with the remarkable ways in which bees communicate."},{"s":"A","text":"So, first of all, who lives in the hive? In summer, a typical colony contains one queen, a small number of drones, and a very large number of workers. The queen's job is to lay eggs, and at the peak of the season she can lay well over a thousand a day. She may live for several years, whereas a summer worker survives for only about six weeks. The drones are the males. You might imagine that they help with the work in the hive, but they don't. Their only function is to mate with young queens from other colonies, and in the autumn the workers push them out of the hive, because they are no longer needed."},{"s":"A","text":"The workers are all female, and what is fascinating is that their jobs change as they get older. During the first few days of adult life, a worker cleans the cells of the comb. After that she becomes a nurse, feeding the larvae. At around two weeks old she starts to build comb, store food and guard the entrance, and only in the last stage of her life, usually after about three weeks, does she become a forager and leave the hive to collect nectar, pollen and water. The wax for the comb is produced by glands on the underside of her abdomen, and the cells she builds are hexagonal, a shape that makes very efficient use of both space and wax."},{"s":"A","text":"Let's turn now to communication. The best known example is the waggle dance, which was decoded by the Austrian scientist Karl von Frisch, who shared a Nobel Prize in 1973. When a forager finds a rich source of nectar, she returns to the hive and dances on the vertical surface of the comb, in complete darkness, surrounded by other workers who follow her movements closely. The central part of the dance is a straight run in which she waggles her body from side to side. The angle of this run, measured from the vertical, shows the direction of the food in relation to the sun. Even when clouds hide the sun, bees can work out where it is from patterns of polarised light in the sky. Now, you might think the speed of the dance shows how far away the food is, but in fact it is the length of time she waggles that gives the distance. The longer the waggle run lasts, the further away the food is. When food is very close to the hive, she may perform a simpler, circular dance that signals only that food is nearby."},{"s":"A","text":"Dancing is only one channel, though. Chemical signals, known as pheromones, are at least as important in holding the colony together. The queen produces a pheromone that spreads through the hive as the workers touch and feed her, and it tells them that she is present and healthy. If she dies, the workers soon detect that the signal has faded, and they choose some young larvae and feed them on a special food called royal jelly, so that they develop into new queens. Other pheromones carry warnings. When a guard bee stings an intruder, she releases an alarm pheromone which, rather surprisingly, smells a little like bananas, and which encourages other guards to join in the defence."},{"s":"A","text":"The colony also manages its own climate. The area where the young are raised is kept at about 35 degrees Celsius, which is a little below our own body temperature. On hot days, workers stand at the entrance and fan their wings to draw air through the hive, and they bring in water, which cools the air as it evaporates. In winter, the bees form a tight cluster around the queen, and they shiver their flight muscles to generate heat."},{"s":"A","text":"Finally, let's consider how a colony reproduces. When the hive becomes overcrowded, the old queen leaves with a large group of workers, known as a swarm, while a new queen takes over in the original hive. The swarm usually settles on a branch nearby, and scouts are sent out to look for a suitable new nest site. Each scout returns and dances to advertise the place she has found, and gradually more of them begin to dance for the best site. When enough scouts are dancing for the same location, the swarm takes off and flies there. In this way, an important decision is reached without any single leader. Thank you for listening."}],"questions":[{"id":"q1","type":"gap","prompt":"Drones: their only function is to ___ with young queens","answer":"mate","max_words":1,"evidence":"Their only function is to mate with young queens from other colonies","why_ar":"قال المحاضر عن الذكور: «Their only function is to mate with young queens»، فالإجابة mate."},{"id":"q2","type":"gap","prompt":"Final stage of a worker's life: works as a ___","answer":"forager","max_words":1,"evidence":"does she become a forager and leave the hive to collect nectar, pollen and water","why_ar":"المرحلة الأخيرة من عمر العاملة: «does she become a forager and leave the hive»، فالإجابة forager."},{"id":"q3","type":"gap","prompt":"Wax is produced by glands on the underside of the worker's ___","answer":"abdomen","max_words":1,"evidence":"produced by glands on the underside of her abdomen","why_ar":"قال المحاضر: «produced by glands on the underside of her abdomen»، فالإجابة abdomen."},{"id":"q4","type":"gap","prompt":"Waggle dance decoded by von Frisch, who shared a Nobel Prize in ___","answer":"1973","max_words":1,"evidence":"shared a Nobel Prize in 1973","why_ar":"قال المحاضر: «shared a Nobel Prize in 1973»، فالسنة هي 1973."},{"id":"q5","type":"gap","prompt":"Angle of the waggle run shows the direction of the food in relation to the position of the ___","answer":"sun","max_words":1,"evidence":"shows the direction of the food in relation to the sun","why_ar":"قال المحاضر: «shows the direction of the food in relation to the sun»؛ والزاوية تُقاس من الاتجاه العمودي لكن الإشارة تخصّ الشمس."},{"id":"q6","type":"gap","prompt":"Length of time of the waggle run shows the ___ to the food","answer":"distance","max_words":1,"evidence":"it is the length of time she waggles that gives the distance","why_ar":"نفى المحاضر أن تكون السرعة هي الدليل، وقال: «it is the length of time she waggles that gives the distance»، فالإجابة distance."},{"id":"q7","type":"gap","prompt":"Larvae chosen to become new queens are fed ___","answer":"royal jelly","max_words":2,"evidence":"feed them on a special food called royal jelly","why_ar":"قال المحاضر: «feed them on a special food called royal jelly»، فالإجابة royal jelly."},{"id":"q8","type":"gap","prompt":"Temperature of the area where young are raised: about ___ degrees Celsius","answer":"35","max_words":1,"evidence":"is kept at about 35 degrees Celsius","why_ar":"قال المحاضر: «is kept at about 35 degrees Celsius»، وهي أقل قليلًا من حرارة جسم الإنسان، فالإجابة 35."},{"id":"q9","type":"gap","prompt":"In winter, the bees form a tight ___ around the queen","answer":"cluster","max_words":1,"evidence":"the bees form a tight cluster around the queen","why_ar":"قال المحاضر: «the bees form a tight cluster around the queen»، فالإجابة cluster."},{"id":"q10","type":"gap","prompt":"A swarm sends out ___ to look for a new nest site","answer":"scouts","max_words":1,"evidence":"scouts are sent out to look for a suitable new nest site","why_ar":"قال المحاضر: «scouts are sent out to look for a suitable new nest site»، فالإجابة scouts.","accept":["scout bees","scout"]}]}
];
